package dev.veltraph.client.hydra;
import java.util.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
final class FloorObservationFailureContainmentTest {
    @Test void failingDiagnosticCacheCannotTurnComputedTrueIntoFalse(){var watcher=new FloorChangeWatcher(10000,1);watcher.observe("anchor",Map.of("a",false,"b",false),100);watcher.diagnosticProbe(d->{throw new AssertionError("cache allocation/sink failure");});assertTrue(watcher.observe("anchor",Map.of("a",true,"b",true),101));assertTrue(watcher.observe("anchor",Map.of("a",true,"b",true),102));}
    @Test void loggerAndFallbackLoggerFailuresCannotEscape(){assertDoesNotThrow(()->FloorDiagnosticReporting.run(()->{throw new IllegalStateException("logger");},failure->{throw new AssertionError("fallback logger");}));}
    @Test void failingMembershipQueryCannotChangeComputedTrue(){var watcher=new FloorChangeWatcher(10000,1);watcher.observe("anchor",Map.of("a",false,"b",false),100);boolean fired=watcher.observe("anchor",Map.of("a",true,"b",true),101);var result=FloorDiagnosticReporting.read(()->{throw new IllegalStateException("native pending query");},"unavailable");assertEquals("unavailable",result);assertTrue(fired);}
    @Test void perCellSupplementalFailureLeavesEvaluatedBooleanAndOtherFacts(){var evaluated=Map.of("feet",true,"head",false);var facts=new HashMap<String,String>();for(var entry:evaluated.entrySet()){var key=entry.getKey();String extra=FloorDiagnosticReporting.read(()->{if(key.equals("feet"))throw new IllegalStateException("shape/fluid read");return "available";},"unavailable");facts.put(key,"solid="+entry.getValue()+","+extra);}assertEquals("solid=true,unavailable",facts.get("feet"));assertEquals("solid=false,available",facts.get("head"));assertTrue(evaluated.get("feet"));}
    @Test void diagnosticFailureLeavesOriginalWindowAndAnchorUpdates(){var watcher=new FloorChangeWatcher(10000,1);watcher.diagnosticProbe(d->{throw new IllegalStateException("report");});assertFalse(watcher.observe("a",Map.of("x",false,"y",false),100));assertTrue(watcher.observe("a",Map.of("x",true,"y",true),101));assertFalse(watcher.observe("b",Map.of("x",false,"y",false),102));assertFalse(watcher.observe("b",Map.of("x",true,"y",false),103));}
    @Test void cachedBooleanDiagnosticRemainsImmutable(){var watcher=new FloorChangeWatcher();var source=new HashMap<String,Boolean>();source.put("cell",true);watcher.observe("anchor",source,100);source.put("cell",false);assertTrue(watcher.diagnostic().after().get("cell"));assertThrows(UnsupportedOperationException.class,()->watcher.diagnostic().after().put("cell",false));}
    @Test void failedNewReportClearsOnlyDiagnosticAndPreservesTrueWindow(){var watcher=new FloorChangeWatcher(10000,1);watcher.observe("anchor",Map.of("a",false,"b",false),100);assertNotNull(watcher.diagnostic());watcher.diagnosticProbe(d->{throw new IllegalStateException("new report failed");});assertTrue(watcher.observe("anchor",Map.of("a",true,"b",true),101));assertNull(watcher.diagnostic());assertTrue(watcher.observe("anchor",Map.of("a",true,"b",true),102));assertNull(watcher.diagnostic());watcher.diagnosticProbe(d->{});assertTrue(watcher.observe("anchor",Map.of("a",true,"b",true),103));assertEquals(2,watcher.diagnostic().windowCount());}
}
